META={
'efeitos/A01-Glassmorphism-Vidro-Fosco':('A01','Glassmorphism — Vidro Fosco','Painéis translúcidos com blur real demonstrados em um dashboard com camadas visíveis.','fundos-e-telas'),
'efeitos/A02-Vidro-Escuro':('A02','Vidro Escuro','Vidro dark aplicado sobre fotografia em uma interface de arquitetura.','fundos-e-telas'),
'efeitos/A03-Vidro-Liquido':('A03','Vidro Líquido','Material com reflexos móveis e sensação de refração aplicado a um player.','fundos-e-telas'),
'efeitos/A06-Efeito-Acrilico':('A06','Efeito Acrílico','Material acrílico translúcido com granulação aplicado a um painel de controles.','fundos-e-telas')}
def page(block,id_,name,desc,slug):
 esc=html.escape(block)
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{id_} — {name}</title><style>*{{box-sizing:border-box}}html,body{{margin:0;background:#000;color:#f7f3e9;font-family:Arial,sans-serif}}.back{{position:fixed;z-index:30;left:16px;top:16px;width:46px;height:46px;border-radius:50%;border:1px solid #ffffff22;background:#08090cb8;color:#fff;cursor:pointer;backdrop-filter:blur(12px)}}.demo{{min-height:100svh;display:grid;place-items:center;padding:28px 18px;overflow:hidden}}.tech{{background:#08090c;padding:46px clamp(20px,5vw,72px) 70px;border-top:1px solid #ffffff12}}.wrap{{max-width:1180px;margin:auto}}.id{{color:#d1ad73;font-weight:800;letter-spacing:.16em;font-size:12px}}h1{{font:500 clamp(34px,5vw,60px) Georgia,serif;margin:8px 0 10px}}.tech p{{color:#aaa69e;line-height:1.7;max-width:800px}}.tools{{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}}.btn{{color:#fff;text-decoration:none;border:1px solid #ffffff20;background:#111318;padding:10px 14px;border-radius:9px;font-weight:700}}button.btn{{cursor:pointer}}textarea{{width:100%;min-height:380px;border:1px solid #ffffff18;border-radius:14px;background:#111318;color:#d7d9dd;padding:18px;font:12px/1.6 Consolas,monospace}}</style></head><body><button class="back" onclick="location.href='../../index.html#categoria={slug}'">←</button><section class="demo">{block}</section><section class="tech"><div class="wrap"><div class="id">{id_}</div><h1>{name}</h1><p>{desc} Situação: candidato.</p><div class="tools"><button class="btn" id="copy">Copiar código</button><a class="btn" href="bloco-pronto.html" target="_blank">Abrir HTML</a><a class="btn" href="bloco-pronto.txt" target="_blank">Abrir TXT</a></div><textarea id="source" spellcheck="false">{esc}</textarea></div></section><script>document.getElementById('copy').onclick=async e=>{{const s=document.getElementById('source').value;try{{await navigator.clipboard.writeText(s)}}catch{{document.getElementById('source').select();document.execCommand('copy')}}e.currentTarget.textContent='Copiado';setTimeout(()=>e.currentTarget.textContent='Copiar código',1200)}};</script></body></html>'''
for base,(id_,name,desc,slug) in META.items():
 block=FILES[base+'/bloco-pronto.html'];FILES[base+'/bloco-pronto.txt']=block;FILES[base+'/index.html']=page(block,id_,name,desc,slug)
for path,content in FILES.items():
 p=Path(path);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
print('\n'.join(FILES))
